    "bu-pi-server": "./dist/server.js"
  },
  "publishConfig": {
    "access": "public"
  }
}

import type { StreamFn } from '@earendil-works/pi-agent-core';
import { createAssistantMessageEventStream, type AssistantMessage } from '@earendil-works/pi-ai';

/** Bound connection setup and the entire response, even if a transport ignores abort. */
export function deadlineStream(streamFn: StreamFn, timeoutMs: number): StreamFn {
  return (model, context, options) => {
    const output = createAssistantMessageEventStream();
    const controller = new AbortController();
    let ended = false;
    let partial: AssistantMessage | undefined;
    let timer: ReturnType<typeof setTimeout> | undefined;
    const cleanup = () => {
      clearTimeout(timer);
      options?.signal?.removeEventListener('abort', cancel);
    };
    const fail = (message: string, cancelled = false) => {
      if (ended) return;
      ended = true;
      cleanup();
      // Freeze partial evidence. A late provider response must not mutate run history.
      const error: AssistantMessage = {
        role: 'assistant',
        content: [],
        api: model.api,
        provider: model.provider,
        model: model.id,
        usage: {
          input: 0,
          output: 0,
          cacheRead: 0,
          cacheWrite: 0,
          totalTokens: 0,
          cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
        },
        timestamp: Date.now(),
        ...(partial ? structuredClone(partial) : {}),
        stopReason: cancelled ? 'aborted' : 'error',
        errorMessage: message,
      };
      output.push({ type: 'error', reason: error.stopReason as 'error' | 'aborted', error });
      output.end();
      controller.abort();
    };
    const cancel = () => fail('Model request cancelled.', true);
    options?.signal?.addEventListener('abort', cancel, { once: true });
    if (options?.signal?.aborted) cancel();
    else {
      timer = setTimeout(() => fail(`Model stream exceeded ${timeoutMs} ms.`), timeoutMs);
      void (async () => {
        try {
          const source = await streamFn(model, context, { ...options, signal: controller.signal });
          if (ended) return;
          for await (const event of source) {
            if (ended) return;
            if ('partial' in event) partial = event.partial;
            if (event.type === 'done' || event.type === 'error') {
              ended = true;
              cleanup();
              output.push(event);
              output.end();
              return;
            }
            output.push(event);
          }
          fail('Model stream ended before a terminal response event.');
        } catch (error) {
          fail(error instanceof Error ? error.message : String(error));
        }
      })();
    }
    return output;
  };
}

import { Browser, BrowserUse } from '@browser_use/pi';

const task = process.argv.slice(2).join(' ');
if (!task) throw new Error('Usage: node examples/research.ts "Your browser task"');
const agent = await BrowserUse.create({
  model: process.env.MODEL || 'openrouter/openai/gpt-5.6-luna',
  browser:
    process.env.BROWSER === 'cloud'
      ? Browser.cloud({ apiKey: process.env.BROWSER_USE_API_KEY ?? '' })
      : process.env.BROWSER_CDP_URL
        ? { cdpUrl: process.env.BROWSER_CDP_URL }
        : Browser.chromium(),
  workspace: process.env.WORKSPACE || './artifacts/research',
});
const controller = new AbortController();
const cancel = () => controller.abort();
process.once('SIGINT', cancel);
try {
  const result = await agent.run(task, {
    signal: controller.signal,
    maxSteps: 30,
    timeoutMs: 300_000,
    maxCostUsd: 2,
    onEvent(event) {
      if (event.type === 'tool_execution_start') process.stderr.write(`→ ${event.toolName}\n`);
      if (event.type === 'message_update' && event.assistantMessageEvent.type === 'text_delta')
        process.stderr.write(event.assistantMessageEvent.delta);
    },
  });
  console.log(JSON.stringify(result, null, 2));
  if (result.status !== 'completed') process.exitCode = 1;
} finally {
  process.removeListener('SIGINT', cancel);
  await agent.close();
}

import {
  createCodingTools,
  createWriteTool,
  type WriteToolInput,
} from '@earendil-works/pi-coding-agent';
import type { AgentTool } from '@earendil-works/pi-agent-core';
import { mkdir, realpath, writeFile } from 'node:fs/promises';
import { isAbsolute, relative, sep } from 'node:path';

/** Observe the path Pi actually wrote, including its own path normalization. Never replay/move it. */
async function writeWithLocation(
  workspace: string,
  id: string,
  args: WriteToolInput,
  signal?: AbortSignal,
) {
  let writtenPath: string | undefined;
  const writer = createWriteTool(workspace, {
    operations: {
      mkdir: async (path) => {
        await mkdir(path, { recursive: true });
      },
      writeFile: async (path, content) => {
        await writeFile(path, content, 'utf8');
        writtenPath = path;
      },
    },
  });
  const result = await writer.execute(id, args, signal);
  try {
    const [root, file] = await Promise.all([realpath(workspace), realpath(writtenPath!)]);
    const path = relative(root, file);
    if (path !== '..' && !path.startsWith(`..${sep}`) && !isAbsolute(path)) return result;
    result.content.push({
      type: 'text',
      text: `Delivery warning: the write succeeded outside workspace ${JSON.stringify(workspace)} at ${JSON.stringify(file)}. BrowserUse.files() does not include this path. If this is a deliverable, save a copy inside workspace and reference that copy. The existing file has not been moved or rewritten.`,
    });
  } catch {
    // Observation failure must not turn a successful write into a retryable mutation failure.
    result.content.push({
      type: 'text',
      text: 'Delivery warning: the write succeeded, but its location could not be verified. Check the saved file and workspace before claiming delivery.',
    });
  }
  return result;
}

/** Pi's file and shell tools work independently of the browser/REPL process. */
export function researchTools(
  workspace: string,
  timeoutMs: number,
  shellEnv: Record<string, string> = {},
  defaultTimeoutMs = timeoutMs,
): AgentTool[] {
  return createCodingTools(workspace, {
    bash: {
      exposeSessionEnvironment: false,
      spawnHook: (context) => ({
        ...context,
        env: {
          PATH: process.env.PATH ?? '/usr/bin:/bin',
          LANG: 'en_US.UTF-8',
          HOME: workspace,
          TMPDIR: workspace,
          ...shellEnv,
        },
      }),
    },
  }).map((tool) => ({
    ...tool,
    executionMode: 'sequential',
    replay: 'never',
    execute: (id, args, signal, update) => {
      if (tool.name === 'write')
        return writeWithLocation(workspace, id, args as WriteToolInput, signal);
      const input = args as { command: string; timeout?: number };
      return tool.execute(
        id,
        tool.name === 'bash'
          ? {
              ...input,
              timeout: Math.min(input.timeout ?? defaultTimeoutMs / 1000, timeoutMs / 1000),
            }
          : args,
        signal,
        update,
      );
    },
  }));
}

import {
  Agent,
  type AgentMessage,
  type AgentTool,
  type StreamFn,
} from '@earendil-works/pi-agent-core';
import type { Model, Api, ToolChoice, Usage } from '@earendil-works/pi-ai';
import { Type, type TSchema } from 'typebox';
import { Check, Errors } from 'typebox/value';
import { CellError, type BrowserRuntime } from './runtime.js';
import { Observer } from './observer.js';
import { RunContext, conversation } from './context.js';
import { deadlineStream } from './model-stream.js';
import { researchTools } from './research-tools.js';
import type { BrowserUseOptions, RunOptions, RunResult, StopReason } from './types.js';
import { redact } from './history.js';
import { SEARCH_PROMPT, SYSTEM_PROMPT } from './prompt.js';
import { AX_PROMPT } from './ax.js';
import { positiveInteger } from './protocol.js';
import { bounded, type RunControl } from './control.js';

export const zeroUsage = (): Usage => ({
  input: 0,
  output: 0,
  cacheRead: 0,
  cacheWrite: 0,
  totalTokens: 0,
  cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
});
// Failures worth one more inference call. Anchored where a trailing access denial must not retry.
const TRANSIENT_MODEL_ERRORS = [
  /^OpenAI API error \(5\d{2}\): /,
  /^Connection error\.$/,
  /stream ended before a terminal|Model stream exceeded|terminated|ECONNRESET|socket hang up|Unable to verify model access right now\. Please retry\./i,
  /^(?:(?:server_error|unknown): )?Sorry, something went wrong\.$/,
  /^An error occurred while processing your request\. You can retry your request,/,
  /^The server had an error while processing your request\./,
  /^The service is temporarily unavailable\.$/,
  /^Rate limit reached for .* Please try again in [\d.]+m?s\./,
  /^peer closed connection without sending complete message body/,
  /^Server disconnected without sending a response\.$/,
  /^(?:\[Errno \d+\] )?Connection reset by peer$/,
  /^Request timed out\.$/,
  /^stream inactive >\d+s$/,
];
// httpx and openai transport failures, relayed bare ("ReadError") or with their message.
const TRANSIENT_TRANSPORT_ERRORS =
  /^(?:ReadError|ReadTimeout|RemoteProtocolError|APITimeoutError)(?::|$)/;
/** A proxy that relays a mid-stream upstream failure prefixes it with the exception class
 * ("APIError: ..."); the message after that prefix decides. */
export function transientModelError(message: string | undefined): boolean {
  const text = message ?? '';
  const detail = text.replace(/^[A-Za-z]+(?:Error|Exception|Timeout): /, '');
  return (
    TRANSIENT_TRANSPORT_ERRORS.test(text) ||
    TRANSIENT_MODEL_ERRORS.some((pattern) => pattern.test(detail))
  );
}

function sumUsage(messages: AgentMessage[]): Usage {
  const result = zeroUsage();
  for (const message of messages) {
    if (message.role !== 'assistant') continue;
    for (const key of ['input', 'output', 'cacheRead', 'cacheWrite', 'totalTokens'] as const)
      result[key] += message.usage[key];
    for (const key of ['input', 'output', 'cacheRead', 'cacheWrite', 'total'] as const)
      result.cost[key] += message.usage.cost[key];
  }
  return result;
}

export async function runAgent(
  runtime: BrowserRuntime,
  model: Model<Api>,
  config: BrowserUseOptions & { streamFn: StreamFn },
  workspace: string,
  task: string,
  schema: TSchema,
  options: RunOptions,
  session?: {
    messages: AgentMessage[];
    control: RunControl;
    save: (messages: AgentMessage[]) => void;
    eventsPath?: string;
  },
): Promise<RunResult<unknown>> {
  const maxSteps = positiveInteger('maxSteps', options.maxSteps ?? 40);
  const timeoutMs = positiveInteger('timeoutMs', options.timeoutMs ?? 300_000);
  const maxContextChars = positiveInteger('maxContextChars', options.maxContextChars ?? 240_000);
  if (
    options.maxCostUsd !== undefined &&
    (!Number.isFinite(options.maxCostUsd) || options.maxCostUsd <= 0)
  ) {
    throw new Error('maxCostUsd must be a finite positive number.');
  }
  if (options.compaction !== undefined && typeof options.compaction !== 'boolean')
    throw new Error('compaction must be boolean.');
  runtime.beginRun();
  const start = Date.now();
  let previousMessages = session?.messages.length ?? 0;
  const hookTimeout = config.hookTimeoutMs ?? 30_000;
  let steps = 0;
  let finishRepairs = 0;
  let providerRetries = 0;
  let retriedUsage = zeroUsage();
  let finalizing = false;
  let compactionFailed = false;
  const warnings: string[] = [];
  const context = new RunContext(
    model,
    deadlineStream(
      (selected, request, settings) =>
        config.streamFn(selected, redact(request, config.redact ?? []), settings),
      config.compactionTimeoutMs ?? 120_000,
    ),
    workspace,
    maxContextChars,
    options.compaction !== false,
    config.redact ?? [],
  );
  let completion: { output: unknown; text: string } | undefined;
  let stopped: StopReason | undefined;
  const codeParameters = Type.Object({ code: Type.String({ minLength: 1 }) });
  const cellFailures = new Map<string, CellError>();
  const javascript: AgentTool<typeof codeParameters> = {
    name: 'javascript',
    label: 'Browser JavaScript',
    description: `Execute JavaScript in a persistent Node REPL with raw CDP. Cell deadline: ${config.cellTimeoutMs ?? 30_000} ms. Checkpoint small batches before the deadline. Use screenshot() for native images.`,
    parameters: codeParameters,
    executionMode: 'sequential',
    replay: 'never',
    execute: async (_id, params: { code: string }, signal) => {
      let result;
      try {
        result = await runtime.execute(params.code, config.cellTimeoutMs ?? 30_000, signal);
      } catch (error) {
        if (!(error instanceof CellError)) throw error;
        // Pi converts thrown tools to text-only errors. Restore their native evidence
        // in afterToolCall while retaining Pi's error flag and application hook control.
        cellFailures.set(_id, error);
        throw new Error(
          `${error.message}\nState reset: ${error.stateReset}. Actions may already have happened.\nPartial output: ${error.result.text}\nCaptured output file: ${error.result.outputFile ?? '(none)'}`,
        );
      }
      return {
        content: [{ type: 'text', text: result.text }, ...result.images],
        details: {
          outputFile: result.outputFile,
          targetId: result.targetId,
          observationTargetId: result.observationTargetId,
        },
      };
    },
  };
  const acceptResult = async (output: unknown, signal?: AbortSignal) => {
    if (!Check(schema, output))
      throw new Error(
        `Final result does not match schema: ${JSON.stringify(Errors(schema, output).slice(0, 5)).slice(0, 2000)}`,
      );
    if (config.validateResult) {
      const feedback = await bounded(
        () => config.validateResult!(output, signal),
        hookTimeout,
        signal,
      );
      if (feedback) throw new Error(`Result rejected: ${feedback}`);
    }
    signal?.throwIfAborted();
    const text = typeof output === 'string' ? output : JSON.stringify(output);
    if (text === undefined) throw new Error('The final result must be JSON serializable.');
    completion = { output, text };
    return {
      content: [{ type: 'text' as const, text: 'Result accepted.' }],
      details: {},
      terminate: true,
    };
  };
  const resultParameters = Type.Object({ result: schema });
  const finish: AgentTool<typeof resultParameters> = {
    name: 'finish',
    label: 'Deliver result',
    description:
      'Submit the verified final result, matching this schema. For data already in JavaScript, prefer finish_from_js to avoid rewriting it. This ends the task.',
    parameters: resultParameters,
    executionMode: 'sequential',
    execute: async (_id, params: { result: unknown }, signal) =>
      acceptResult(params.result, signal),
  };
  const expressionParameters = Type.Object({ expression: Type.String({ minLength: 1 }) });
  const finishFromJs: AgentTool<typeof expressionParameters> = {
    name: 'finish_from_js',
    label: 'Deliver JavaScript value',
    description:
      'Deliver an existing value from the persistent REPL without printing or rewriting it. Expression must match the result schema of finish. For a string result use JSON.stringify(records) or an existing text variable. Evaluated once; ends the task after validation.',
    parameters: expressionParameters,
    executionMode: 'sequential',
    replay: 'never',
    execute: async (_id, params: { expression: string }, signal) =>
      acceptResult(
        await runtime.readResult(params.expression, config.cellTimeoutMs ?? 30_000, signal),
        signal,
      ),
  };
  // OpenAI restricts delivery turns with allowed_tools, so the tool list (part of the cached prompt prefix) stays.
  // Other providers on this api (xAI, gateways) reject allowed_tools; a baseUrl proxy for openai must pass it through.
  const keepTools = model.provider === 'openai' && model.api === 'openai-responses';
  const delivering = () => finalizing || finishRepairs > 0;
  const deliveryTools = ['finish', 'finish_from_js'];
  // pi-ai forwards toolChoice verbatim. 'required': under 'auto' a model can answer with text again and end incomplete.
  const deliveryChoice = {
    type: 'allowed_tools',
    mode: 'required',
    tools: deliveryTools.map((name) => ({ type: 'function', name })),
  } as unknown as ToolChoice;
  const checkBudgets = (messages: AgentMessage[], systemPrompt: string) => {
    if (steps >= maxSteps) stopped = 'max_steps';
    if (
      options.maxCostUsd !== undefined &&
      sumUsage(messages.slice(previousMessages)).cost.total +
        retriedUsage.cost.total +
        context.usage.reduce((sum, usage) => sum + usage.cost.total, 0) >=
        options.maxCostUsd
    )
      stopped = 'cost_limit';
    if (options.compaction === false && !context.fits(messages, systemPrompt))
      stopped = 'context_limit';
    return stopped !== undefined;
  };
  const observer = options.observe
    ? new Observer(
        options.observe,
        positiveInteger('observerTimeoutMs', options.observerTimeoutMs ?? 3000),
      )
    : undefined;
  const journalGuidance = session?.eventsPath
    ? `Run journal (JSON path): ${JSON.stringify(session.eventsPath)}\nRead relevant JSONL events to recover original tool execution times and observations. Event timestamps are not simultaneous page snapshots; never replace missing capture times with report time.\n`
    : '';
  const agent = new Agent({
    streamFn: deadlineStream(
      (selected, request, settings) =>
        config.streamFn(selected, redact(request, config.redact ?? []), {
          ...settings,
          maxTokens: Math.min(selected.maxTokens, 32768, Math.floor(selected.contextWindow * 0.15)),
          ...(delivering() && keepTools ? { toolChoice: deliveryChoice } : {}),
        }),
      config.modelTimeoutMs ?? 300_000,
    ),
    initialState: {
      model,
      messages: session?.messages ?? [],
      systemPrompt: `${SYSTEM_PROMPT}${config.mode === 'ultrafast' ? AX_PROMPT : ''}${config.webSearch ? SEARCH_PROMPT : ''}\nWorkspace directory (JSON string): ${JSON.stringify(workspace)}. Relative file-tool paths and the JavaScript working directory start here. Save deliverables inside this directory; files outside it are not included by BrowserUse.files(). Use relative paths or the exact workspace value, not a guessed parent directory.\n${journalGuidance}${config.sensitiveData ? `Named secrets (values withheld): ${JSON.stringify(Object.fromEntries(Object.entries(config.sensitiveData).map(([name, entry]) => [name, entry.domains])))}. Use await fillSecret(name, backendNodeId, page) on an input found in the AX tree. Never read back, print or save credentials.\n` : ''}${config.instructions ?? ''}`,
      thinkingLevel: config.reasoning ?? 'medium',
      tools: [
        javascript,
        finish,
        finishFromJs,
        ...(config.researchTools
          ? researchTools(
              workspace,
              config.shellTimeoutMs ?? config.cellTimeoutMs ?? 30_000,
              config.shellEnv,
              // Like common coding agents: two minutes unless the command asks for longer.
              config.shellTimeoutMs ? Math.min(config.shellTimeoutMs, 120_000) : undefined,
            )
          : []),
        ...(config.tools ?? []),
      ],
    },
    toolExecution: 'sequential',
    transformContext: async (messages, signal) => {
      try {
        if (!compactionFailed) await context.prepare(messages, agent.state.systemPrompt, signal);
      } catch (error) {
        compactionFailed = true;
        warnings.push(`Compaction unavailable: ${String(error)}`);
      }
      signal?.throwIfAborted();
      if (!context.fits(messages, agent.state.systemPrompt)) {
        stopped = 'context_limit';
        throw new Error('Context limit reached; checkpoint files and transcript retained.');
      }
      if (
        options.maxCostUsd !== undefined &&
        sumUsage(messages.slice(previousMessages)).cost.total +
          retriedUsage.cost.total +
          context.usage.reduce((sum, u) => sum + u.cost.total, 0) >=
          options.maxCostUsd
      ) {
        stopped = 'cost_limit';
        throw new Error('Cost limit reached during context preparation.');
      }
      return context.project(messages);
    },
    prepareNextTurnWithContext: ({ context: current }) => {
      if (
        !finalizing &&
        ((maxSteps >= 2 && steps >= maxSteps - 1) ||
          Date.now() - start >= timeoutMs * 0.9 ||
          (options.maxCostUsd !== undefined &&
            sumUsage(current.messages.slice(previousMessages)).cost.total +
              retriedUsage.cost.total +
              context.usage.reduce((sum, usage) => sum + usage.cost.total, 0) >=
              options.maxCostUsd * 0.9))
      ) {
        finalizing = true;
        current.messages.push({
          role: 'user',
          content:
            'Budget nearly exhausted. Deliver the verified result now with finish/finish_from_js. Reference saved files; explicitly list missing evidence. Do not perform more browser actions.',
          timestamp: Date.now(),
        });
        if (!keepTools) {
          agent.state.tools = [finish, finishFromJs];
          return { context: { ...current, tools: [finish, finishFromJs] } };
        }
      }
      return undefined;
    },
    beforeToolCall: async (call, signal) => {
      await session?.control.checkpoint(signal);
      if (completion || stopped || signal?.aborted)
        return { block: true, reason: 'The run has ended.', terminate: true };
      if (delivering() && !deliveryTools.includes(call.toolCall.name))
        return { block: true, reason: 'Only finish or finish_from_js can run now.' };
      return config.beforeToolCall
        ? bounded(() => config.beforeToolCall!(call, signal), hookTimeout, signal)
        : undefined;
    },
    afterToolCall: async (call, signal) => {
      const failure = cellFailures.get(call.toolCall.id);
      cellFailures.delete(call.toolCall.id);
      const evidence = failure
        ? {
            content: [...call.result.content, ...failure.result.images],
            details: {
              outputFile: failure.result.outputFile,
              targetId: failure.result.targetId,
              observationTargetId: failure.result.observationTargetId,
              stateReset: failure.stateReset,
            },
          }
        : undefined;
      // Completion validation belongs in validateResult, not a post-effect override.
      if (
        !config.afterToolCall ||
        call.toolCall.name === 'finish' ||
        call.toolCall.name === 'finish_from_js'
      )
        return evidence;
      const observed = evidence ? { ...call, result: { ...call.result, ...evidence } } : call;
      const override = await bounded(
        () => config.afterToolCall!(observed, signal),
        hookTimeout,
        signal,
      );
      return { ...evidence, ...override };
    },
    finishTurn: ({ message, context }): { action: 'end' } | undefined => {
      // Error and aborted responses are hard exits; the old shouldStopAfterTurn never saw them.
      if (message.stopReason === 'error' || message.stopReason === 'aborted') return undefined;
      if (completion || stopped) return { action: 'end' };
      return checkBudgets(context.messages, agent.state.systemPrompt) || finishRepairs > 0
        ? { action: 'end' }
        : undefined;
    },
  });
  // Pi prepends the prompt as a system message; this run's messages start after it and the history.
  previousMessages = agent.state.messages.length;
  if (session)
    session.control.steer = (text) =>
      agent.steer({ role: 'user', content: text, timestamp: Date.now() });
  agent.subscribe((event) => {
    if (event.type === 'turn_start') steps++;
  });
  if (options.onEvent)
    agent.subscribe((event, signal) =>
      bounded(() => options.onEvent!(event, signal), hookTimeout, signal),
    );
  agent.subscribe((event) => {
    if (event.type === 'tool_execution_end') observer?.push(event);
  });
  const cancel = () => {
    stopped = 'cancelled';
    agent.abort();
  };
  options.signal?.addEventListener('abort', cancel, { once: true });
  const timer = setTimeout(() => {
    stopped = 'timeout';
    agent.abort();
  }, timeoutMs);
  let error: string | undefined;
  try {
    if (options.signal?.aborted) stopped = 'cancelled';
    else if (
      !context.fits(
        [...agent.state.messages, { role: 'user', content: task, timestamp: Date.now() }],
        agent.state.systemPrompt,
      ) &&
      conversation(agent.state.messages).length === 0
    )
      stopped = 'context_limit';
    else if (
      !checkBudgets(
        [...agent.state.messages, { role: 'user', content: task, timestamp: Date.now() }],
        agent.state.systemPrompt,
      )
    ) {
      await agent.prompt(task);
      const failed = agent.state.messages.at(-1);
      if (
        failed?.role === 'assistant' &&
        failed.stopReason === 'error' &&
        transientModelError(failed.errorMessage) &&
        !checkBudgets(agent.state.messages, agent.state.systemPrompt) &&
        !options.signal?.aborted
      ) {
        // Pi never executes tool calls from an error response. Retry inference once, not actions.
        providerRetries = 1;
        retriedUsage = failed.usage;
        agent.state.messages = agent.state.messages.slice(0, -1);
        await agent.continue();
      }
      const ending = agent.state.messages.findLast((m) => m.role === 'assistant');
      // One delivery-only repair. The original timer, transcript and budgets remain in force.
      if (!completion && !stopped && ending?.role === 'assistant' && ending.stopReason === 'stop') {
        const repair: AgentMessage = {
          role: 'user',
          content: [
            {
              type: 'text',
              text: 'The run ended without a validated delivery. Use finish_from_js for an existing result or finish for a concise answer. Preserve all verified records; report missing evidence honestly. Do not repeat browser actions. This is the single delivery repair turn.',
            },
          ],
          timestamp: Date.now(),
        };
        if (!checkBudgets([...agent.state.messages, repair], agent.state.systemPrompt)) {
          finishRepairs = 1;
          if (!keepTools) agent.state.tools = [finish, finishFromJs];
          await agent.prompt(repair);
        }
      }
    }
  } catch (cause) {
    error = cause instanceof Error ? cause.message : String(cause);
    stopped ??= 'error';
  } finally {
    clearTimeout(timer);
    await observer?.close(stopped === 'cancelled' || stopped === 'timeout');
    warnings.push(...(observer?.warnings ?? []));
    options.signal?.removeEventListener('abort', cancel);
    // Saved history excludes the system message so a restored run gets the current prompt.
    session?.save(conversation(context.project(agent.state.messages)));
    session?.control.finish();
  }
  const last = agent.state.messages.slice(previousMessages).findLast((m) => m.role === 'assistant');
  // A failed delivery repair must not erase useful text from the original ending.
  const text =
    agent.state.messages
      .slice(previousMessages)
      .filter((m) => m.role === 'assistant')
      .map((m) =>
        m.content
          .filter((c) => c.type === 'text')
          .map((c) => c.text)
          .join('\n'),
      )
      .findLast((value) => value.trim().length > 0) ?? '';
  const usage = sumUsage(agent.state.messages.slice(previousMessages));
  for (const extra of [retriedUsage, ...context.usage]) {
    for (const key of ['input', 'output', 'cacheRead', 'cacheWrite', 'totalTokens'] as const)
      usage[key] += extra[key];
    for (const key of ['input', 'output', 'cacheRead', 'cacheWrite', 'total'] as const)
      usage.cost[key] += extra.cost[key];
  }
  const metrics = {
    steps,
    finishRepairs,
    durationMs: Date.now() - start,
    usage,
    compactions: context.compactions,
    providerRetries,
    ...(warnings.length ? { warnings } : {}),
    workspace,
    model: config.model,
  };
  if (completion && !stopped) return { ...metrics, status: 'completed', ...completion };
  if (
    last?.role === 'assistant' &&
    (last.stopReason === 'error' || last.stopReason === 'aborted')
  ) {
    stopped ??= 'error';
    error ??= last.errorMessage ?? 'Model request failed.';
  }
  const observation = agent.state.messages
    .slice(previousMessages)
    .findLast((m) => m.role === 'toolResult');
  const fallback =
    observation?.role === 'toolResult'
      ? observation.content
          .filter((c) => c.type === 'text')
          .map((c) => c.text)
          .join('\n')
      : '';
  return {
    ...metrics,
    status: stopped ?? 'incomplete',
    text: text || (fallback ? `Last tool observation (unfinished):\n${fallback}` : ''),
    ...(completion
      ? { partial: { value: completion.output } }
      : runtime.partial
        ? { partial: structuredClone(runtime.partial) }
        : {}),
    ...(error ? { error } : {}),
  };
}

import { spawn, execFile } from 'node:child_process';
import { access, mkdir, mkdtemp, open, readFile, realpath, rm, stat } from 'node:fs/promises';
import { tmpdir, homedir } from 'node:os';
import { join } from 'node:path';
import { setTimeout as delay } from 'node:timers/promises';

export interface LocalBrowserOptions {
  headless?: boolean;
  channel?: 'chrome' | 'msedge';
  executablePath?: string;
  profileDir?: string;
}
export interface CloudBrowserOptions {
  apiKey: string;
  profileId?: string;
  timeoutMinutes?: number;
  proxyCountryCode?: string;
}
export interface ChromeBrowserOptions {
  cdpUrl?: string;
  /** User-data root containing DevToolsActivePort, not its Default subdirectory. */
  profileDir?: string;
  targetId?: string;
  /** macOS only: accept Chrome’s exact remote-debugging sheet while connecting. */
  approveConnection?: boolean;
}
export type BrowserOptions =
  | {
      kind: 'pending';
      /** How long a browser cell waits for connectBrowser(). Default 60 s. */ timeoutMs?: number;
    }
  | ({ kind: 'cloud' } & CloudBrowserOptions)
  | ({ kind: 'chromium' } & LocalBrowserOptions)
  | ({ kind: 'chrome' } & ChromeBrowserOptions)
  | ({ kind?: never; cdpUrl: string; targetId?: string } & {
      [K in keyof LocalBrowserOptions]?: never;
    })
  | ({ kind?: never; cdpUrl?: never; targetId?: never } & LocalBrowserOptions);

/** Declarative browser choices. BrowserUse owns the resulting connection lifecycle. */
export const Browser = {
  cloud: (options: CloudBrowserOptions): BrowserOptions => ({ ...options, kind: 'cloud' }),
  chromium: (options: LocalBrowserOptions = {}): BrowserOptions => ({
    ...options,
    kind: 'chromium',
  }),
  chrome: (options: ChromeBrowserOptions = {}): BrowserOptions => ({ ...options, kind: 'chrome' }),
  /** No browser yet: the model starts at once; the first browser cell waits for connectBrowser(). */
  pending: (options: { timeoutMs?: number } = {}): BrowserOptions => ({
    ...options,
    kind: 'pending',
  }),
};

/** Same profile discovery convention as Browser Harness on macOS, Linux and Windows. */
export function chromeProfileDirs(
  platform = process.platform,
  home = homedir(),
  local = process.env.LOCALAPPDATA,
) {
  if (platform === 'darwin') return [join(home, 'Library/Application Support/Google/Chrome')];
  if (platform === 'win32')
    return [join(local || join(home, 'AppData/Local'), 'Google/Chrome/User Data')];
  return [join(home, '.config/google-chrome'), join(home, '.config/chromium')];
}
async function discoverChrome(options: ChromeBrowserOptions) {
  for (const profile of options.profileDir ? [options.profileDir] : chromeProfileDirs()) {
    try {
      const [port, path] = (await readFile(join(profile, 'DevToolsActivePort'), 'utf8'))
        .trim()
        .split('\n');
      if (
        !port ||
        !/^\d+$/.test(port) ||
        +port < 1 ||
        +port > 65535 ||
        !path?.startsWith('/devtools/browser/')
      )
        continue;
      const response = await fetch(`http://127.0.0.1:${port}/json/version`, {
        signal: AbortSignal.timeout(1500),
      });
      // Chrome 147 can disable HTTP discovery for its default profile.
      if (response.status === 404) return `ws://127.0.0.1:${port}${path}`;
      if (!response.ok) continue;
      const info = (await response.json()) as { webSocketDebuggerUrl?: string };
      if (info.webSocketDebuggerUrl) return info.webSocketDebuggerUrl;
    } catch {}
  }
  throw new Error(
    'No running Chrome debugging endpoint found. Enable chrome://inspect/#remote-debugging and accept Chrome’s connection prompt, or pass Browser.chrome({ cdpUrl }). No browser was launched or profile copied.',
  );
}

async function openCloud(options: CloudBrowserOptions) {
  if (typeof options.apiKey !== 'string' || !options.apiKey.trim())
    throw new Error('Browser.cloud requires apiKey.');
  const timeout = options.timeoutMinutes ?? 30;
  if (!Number.isInteger(timeout) || timeout <= 0 || timeout > 240)
    throw new Error('timeoutMinutes must be an integer from 1 to 240.');
  const request = async (path: string, method: string, body: object) => {
    const response = await fetch(`https://api.browser-use.com/api/v3${path}`, {
      method,
      headers: { 'X-Browser-Use-API-Key': options.apiKey, 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(30_000),
      redirect: 'error',
    });
    if (!response.ok) throw new Error(`Browser Use Cloud ${method} failed (${response.status}).`);
    return response;
  };
  // Never retry provisioning: an ambiguous POST can already have created a billable browser.
  const data = (await (
    await request('/browsers', 'POST', {
      timeout,
      enableRecording: false,
      ...(options.profileId ? { profileId: options.profileId } : {}),
      ...(options.proxyCountryCode ? { proxyCountryCode: options.proxyCountryCode } : {}),
    })
  ).json()) as { id?: string; cdpUrl?: string; liveUrl?: string };
  if (typeof data.id !== 'string' || !data.id)
    throw new Error(
      'Cloud response missing browser id; check the Cloud dashboard for an orphaned browser.',
    );
  let closing: Promise<void> | undefined;
  const close = () =>
    (closing ??= request(`/browsers/${encodeURIComponent(data.id!)}`, 'PATCH', { action: 'stop' })
      .then(() => {})
      .catch((error) => {
        closing = undefined;
        throw error;
      }));
  try {
    if (
      typeof data.cdpUrl !== 'string' ||
      !['ws:', 'wss:', 'http:', 'https:'].includes(new URL(data.cdpUrl).protocol)
    )
      throw new Error('Cloud response missing valid cdpUrl.');
    return { endpoint: data.cdpUrl, close };
  } catch (error) {
    try {
      await close();
    } catch {
      throw new Error(
        `Invalid Cloud response and cleanup failed for browser ${data.id}; stop it in the Cloud dashboard.`,
      );
    }
    throw error;
  }
}

async function executable(options: LocalBrowserOptions) {
  if (options.executablePath) {
    await access(options.executablePath);
    return options.executablePath;
  }
  const candidates =
    process.platform === 'darwin'
      ? [
          options.channel === 'msedge'
            ? '/Applications/Microsoft Edge.app/Contents/MacOS/Microsoft Edge'
            : '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
          '/Applications/Chromium.app/Contents/MacOS/Chromium',
        ]
      : process.platform === 'win32'
        ? [
            join(
              process.env.PROGRAMFILES ?? 'C:\\Program Files',
              options.channel === 'msedge'
                ? 'Microsoft/Edge/Application/msedge.exe'
                : 'Google/Chrome/Application/chrome.exe',
            ),
          ]
        : options.channel === 'msedge'
          ? ['/usr/bin/microsoft-edge']
          : ['/usr/bin/google-chrome', '/usr/bin/chromium', '/usr/bin/chromium-browser'];
  for (const path of candidates) {
    try {
      await access(path);
      return path;
    } catch {}
  }
  throw new Error(
    'Chrome not found. Install Chrome or set browser.executablePath / browser.cdpUrl.',
  );
}

/** Local Chrome has an isolated temporary profile; external Chrome always belongs to the caller. */
export function validCdpUrl(cdpUrl: string): string {
  if (
    typeof cdpUrl !== 'string' ||
    !['http:', 'https:', 'ws:', 'wss:'].includes(new URL(cdpUrl).protocol)
  )
    throw new Error('cdpUrl must be an HTTP(S) or WebSocket endpoint.');
  return cdpUrl;
}

export async function openBrowser(options: BrowserOptions = {}) {
  if (
    options.kind !== undefined &&
    !['cloud', 'chrome', 'chromium', 'pending'].includes(options.kind)
  )
    throw new Error(
      'Unknown browser kind. Use Browser.cloud, Browser.chromium, Browser.chrome or Browser.pending.',
    );
  if (options.kind === 'pending') return { endpoint: '', close: async () => {} };
  if (options.kind === 'cloud') return openCloud(options);
  if (options.kind === 'chrome') {
    if (options.approveConnection !== undefined && typeof options.approveConnection !== 'boolean')
      throw new Error('approveConnection must be boolean.');
    if (options.approveConnection && process.platform !== 'darwin')
      throw new Error('approveConnection is supported only on macOS.');
    const endpoint = options.cdpUrl ?? (await discoverChrome(options));
    if (!['http:', 'https:', 'ws:', 'wss:'].includes(new URL(endpoint).protocol))
      throw new Error('Invalid Chrome CDP endpoint.');
    return { endpoint, close: async () => {} };
  }
  if ('cdpUrl' in options && options.cdpUrl) {
    if (['headless', 'channel', 'executablePath', 'profileDir'].some((key) => key in options))
      throw new Error('cdpUrl cannot be combined with local browser options.');
    return { endpoint: validCdpUrl(options.cdpUrl), close: async () => {} };
  }
  const path = await executable(options as LocalBrowserOptions);
  const persistent = !!options.profileDir;
  if (options.profileDir) await mkdir(options.profileDir, { recursive: true, mode: 0o700 });
  const profile = options.profileDir
    ? await realpath(options.profileDir)
    : await mkdtemp(join(tmpdir(), 'browser-use-'));
  const lockPath = join(profile, '.bu-pi.lock');
  const lock = await open(lockPath, 'wx', 0o600).catch(() => {
    throw new Error(
      `Browser profile is locked: ${profile}. Close its owner. After a crash, verify Chrome and the SDK have exited before removing .bu-pi.lock.`,
    );
  });
  await lock.writeFile(JSON.stringify({ pid: process.pid, createdAt: new Date().toISOString() }));
  const launchedAt = Date.now();
  const child = spawn(
    path,
    [
      `--user-data-dir=${profile}`,
      '--remote-debugging-port=0',
      '--remote-debugging-address=127.0.0.1',
      '--no-first-run',
      '--no-default-browser-check',
      '--window-size=1440,900',
      ...(options.headless === false ? [] : ['--headless=new']),
      'about:blank',
    ],
    { stdio: 'ignore' },
  );
  let launchError: Error | undefined;
  child.on('error', (error) => {
    launchError = error;
  });
  let closing: Promise<void> | undefined;
  const close = () =>
    (closing ??= (async () => {
      if (child.exitCode === null && child.signalCode === null && child.pid) {
        const exited = new Promise<void>((resolve) => child.once('exit', () => resolve()));
        child.kill('SIGTERM');
        const timer = setTimeout(() => child.kill('SIGKILL'), 2000);
        await exited;
        clearTimeout(timer);
      }
      await lock.close();
      await rm(lockPath, { force: true });
      if (!persistent) await rm(profile, { recursive: true, force: true });
    })());
  try {
    const deadline = Date.now() + 15_000;
    while (Date.now() < deadline) {
      if (launchError) throw launchError;
      if (child.exitCode !== null || child.signalCode !== null)
        throw new Error('Chrome exited before exposing CDP.');
      try {
        if ((await stat(join(profile, 'DevToolsActivePort'))).mtimeMs < launchedAt - 1)
          throw new Error('Waiting for a fresh DevTools endpoint.');
        const [port, path] = (await readFile(join(profile, 'DevToolsActivePort'), 'utf8'))
          .trim()
          .split('\n');
        if (port && path) return { endpoint: `ws://127.0.0.1:${port}${path}`, close };
      } catch {}
      await delay(50);
    }
    throw new Error('Chrome did not expose CDP within 15000 ms.');
  } catch (error) {
    await close();
    throw error;
  }
}

/** Narrow AX action from Browser Harness. Never enables debugging or grants Accessibility. */
export function approveChromeConnection(signal: AbortSignal): Promise<string> {
  const script = `using terms from application "System Events"
    on clickAllow(nodeRef)
      try
        if (role of nodeRef as text) is "AXButton" and (description of nodeRef as text) is "Allow" then
          perform action "AXPress" of nodeRef
          return true
        end if
      end try
      try
        repeat with childRef in UI elements of nodeRef
          if my clickAllow(childRef) then return true
        end repeat
      end try
      return false
    end clickAllow
  end using terms from
  tell application "System Events"
    if exists process "Google Chrome" then
      tell process "Google Chrome"
        repeat with w in windows
          try
            repeat with s in sheets of w
              if (name of s as text) is "Allow remote debugging?" then
                if my clickAllow(s) then return "ready"
              end if
            end repeat
          end try
        end repeat
      end tell
    end if
  end tell
  return "not-found"`;
  return new Promise((resolve, reject) => {
    execFile('/usr/bin/osascript', ['-e', script], { timeout: 5000, signal }, (error, stdout) => {
      if (error)
        reject(
          new Error(
            'Chrome approval needs macOS Accessibility permission for the app running Browser Use Pi. Accept Chrome’s prompt manually, or grant that permission.',
          ),
        );
      else resolve(stdout.trim());
    });
  });
}

"""Thin async Python client. One Pi engine; Python callables remain in Python."""

from __future__ import annotations

import asyncio
import inspect
import json
import os
import shutil
from collections.abc import AsyncIterator, Awaitable, Callable
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Self

from pydantic import BaseModel


class BrowserUseError(RuntimeError):
    """An explicit SDK, transport or lifecycle failure."""


def _schema(schema: dict[str, Any]) -> dict[str, Any]:
    """Inline local Pydantic references before nesting a schema in tool parameters."""

    def visit(value: Any, refs: frozenset[str] = frozenset()) -> Any:
        if isinstance(value, list):
            return [visit(item, refs) for item in value]
        if not isinstance(value, dict):
            return value
        if "$ref" in value:
            ref = value["$ref"]
            if not isinstance(ref, str) or not ref.startswith("#/") or ref in refs:
                raise BrowserUseError(
                    "Only non-recursive local JSON Schema references are supported."
                )
            target: Any = schema
            try:
                for key in ref[2:].split("/"):
                    target = target[key.replace("~1", "/").replace("~0", "~")]
            except (KeyError, TypeError) as exc:
                raise BrowserUseError(f"Unresolved schema reference: {ref}") from exc
            # Pydantic uses plain reference nodes. Reject siblings rather than weakening constraints.
            if set(value) - {"$ref", "title", "description"}:
                raise BrowserUseError("Schema reference siblings are unsupported.")
            return visit(target, refs | {ref})
        return {
            key: visit(item, refs)
            for key, item in value.items()
            if key not in {"$defs", "definitions"}
        }

    return visit(schema)


@dataclass(frozen=True)
class Tool:
    name: str
    description: str
    parameters: type[BaseModel]
    execute: Callable[[BaseModel], Any | Awaitable[Any]]


@dataclass(frozen=True)
class RunResult:
    status: str
    output: Any
    text: str
    metadata: dict[str, Any]

    @property
    def partial(self) -> dict[str, Any] | None:
        """Latest published checkpoint, explicitly not a completed schema-validated result."""
        return self.metadata.get("partial")

    @property
    def usage(self) -> dict[str, Any]:
        return self.metadata["usage"]


class BrowserUse:
    """An async session, backed by the packaged Node runtime. Use async context management."""

    def __init__(self) -> None:
        self.workspace = ""
        self._process: asyncio.subprocess.Process | None = None
        self._pending: dict[int, asyncio.Future[Any]] = {}
        self._next_id = 0
        self._write_lock = asyncio.Lock()
        self._tools: dict[str, Tool] = {}
        self._tool_tasks: dict[str, asyncio.Task[None]] = {}
        self._queues: set[asyncio.Queue[Any]] = set()
        self._reader: asyncio.Task[None] | None = None
        self._stderr_task: asyncio.Task[None] | None = None
        self._stderr = ""
        self._closed = False
        self._closing: asyncio.Task[None] | None = None
        self._configuring = False

    @classmethod
    async def create(
        cls,
        *,
        model: str,
        tools: list[Tool] | None = None,
        node: str | None = None,
        server_path: str | Path | None = None,
        **options: Any,
    ) -> BrowserUse:
        agent = await cls.start(tools=tools, node=node, server_path=server_path)
        return await agent.configure(model=model, **options)

    @classmethod
    async def start(
        cls,
        *,
        tools: list[Tool] | None = None,
        node: str | None = None,
        server_path: str | Path | None = None,
    ) -> BrowserUse:
        """Start the Node runtime without a session, so a host can boot it while it
        prepares the options; `configure` then creates the session."""
        self = cls()
        for tool in tools or []:
            if tool.name in self._tools:
                raise ValueError(f"Duplicate tool: {tool.name}")
            self._tools[tool.name] = tool
        executable = node or shutil.which("node")
        if not executable:
            raise BrowserUseError(
                "Node.js 22.19+ is required. Install Node or pass node='/absolute/path/to/node'."
            )
        server = (
            Path(server_path)
            if server_path
            else Path(__file__).with_name("runtime") / "server.mjs"
        )
        if not server.is_file():
            raise BrowserUseError(
                "Packaged JS runtime is missing. Build with npm run build:python, or pass server_path."
            )
        # The agent process receives selected provider keys. Its JS worker receives no environment keys.
        allowed = {
            "PATH",
            "HOME",
            "TMPDIR",
            "TEMP",
            "SYSTEMROOT",
            "SSL_CERT_FILE",
            "NODE_EXTRA_CA_CERTS",
        }
        allowed.update(
            {
                "OPENAI_API_KEY",
                "ANTHROPIC_API_KEY",
                "GOOGLE_API_KEY",
                "GEMINI_API_KEY",
                "OPENROUTER_API_KEY",
                "BROWSER_USE_API_KEY",
            }
        )
        env = {key: value for key, value in os.environ.items() if key in allowed}
        self._process = await asyncio.create_subprocess_exec(
            executable,
            str(server.resolve()),
            stdin=asyncio.subprocess.PIPE,
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.PIPE,
            env=env,
            limit=16_000_001,
        )
        self._reader = asyncio.create_task(self._read())
        self._stderr_task = asyncio.create_task(self._read_stderr())
        try:
            ping = await asyncio.wait_for(self._call("ping"), 10)
            if ping.get("protocol") != 1:
                raise BrowserUseError("Unsupported runtime protocol.")
            version = tuple(int(part) for part in ping["node"].split(".")[:2])
            if version < (22, 19):
                raise BrowserUseError("Node.js 22.19+ is required.")
            return self
        except BaseException:
            await self.close()
            raise

    async def configure(self, *, model: str, **options: Any) -> Self:
        """Create the session on a runtime from `start`; closes it on failure, like `create`."""
        if self._configuring:
            raise BrowserUseError("Session is already configured.")
        self._configuring = True
        try:
            specs = [
                {
                    "name": t.name,
                    "description": t.description,
                    "parameters": _schema(t.parameters.model_json_schema()),
                }
                for t in self._tools.values()
            ]
            result = await asyncio.wait_for(
                self._call("create", {"model": model, **options, "tools": specs}), 30
            )
            self.workspace = result["workspace"]
            return self
        except BaseException:
            await self.close()
            raise

    async def _call(self, method: str, params: dict[str, Any] | None = None) -> Any:
        if self._closed or not self._process or self._process.returncode is not None:
            raise BrowserUseError("Session is closed or runtime exited.")
        self._next_id += 1
        request_id = self._next_id
        future = asyncio.get_running_loop().create_future()
        self._pending[request_id] = future
        try:
            message = (
                json.dumps(
                    {"id": request_id, "method": method, "params": params or {}},
                    allow_nan=False,
                ).encode()
                + b"\n"
            )
            if len(message) > 16_000_000:
                raise BrowserUseError(
                    "Bridge request exceeds 16 MB; use a workspace file."
                )
            async with self._write_lock:
                assert self._process.stdin
                self._process.stdin.write(message)
                await self._process.stdin.drain()
            return await future
        finally:
            self._pending.pop(request_id, None)

    async def _read(self) -> None:
        assert self._process and self._process.stdout
        error: Exception = BrowserUseError(
            "Node runtime exited. JS state is lost; inspect browser state before retrying."
        )
        try:
            while line := await self._process.stdout.readline():
                message = json.loads(line)
                if "id" in message:
                    future = self._pending.get(message["id"])
                    if future and not future.done():
                        if "error" in message:
                            future.set_exception(
                                BrowserUseError(message["error"]["message"])
                            )
                        else:
                            future.set_result(message.get("result"))
                elif message.get("method") == "tool_call":
                    params = message["params"]
                    task = asyncio.create_task(self._execute_tool(params))
                    self._tool_tasks[params["id"]] = task
                    task.add_done_callback(
                        lambda _task, key=params["id"]: self._tool_tasks.pop(key, None)
                    )
                elif message.get("method") == "tool_cancel":
                    task = self._tool_tasks.get(message["params"]["id"])
                    if task:
                        task.cancel()
                elif message.get("method") in {"event", "stream_error"}:
                    self._broadcast(message["params"])
        except (
            ValueError,
            TypeError,
            KeyError,
            ConnectionError,
            asyncio.LimitOverrunError,
        ) as exc:
            error = BrowserUseError(f"Runtime protocol failure: {exc}")
        finally:
            for future in list(self._pending.values()):
                if not future.done():
                    future.set_exception(error)
            for task in list(self._tool_tasks.values()):
                task.cancel()
            self._broadcast(error)

    def _broadcast(self, event: Any) -> None:
        for queue in list(self._queues):
            if queue.full():
                while not queue.empty():
                    queue.get_nowait()
                queue.put_nowait(
                    BrowserUseError(
                        "Event consumer fell behind; read the persisted run log."
                    )
                )
                self._queues.discard(queue)
            else:
                queue.put_nowait(event)

    async def _read_stderr(self) -> None:
        assert self._process and self._process.stderr
        while chunk := await self._process.stderr.read(4096):
            self._stderr = (self._stderr + chunk.decode(errors="replace"))[-16000:]

    async def _execute_tool(self, params: dict[str, Any]) -> None:
        try:
            tool = self._tools[params["name"]]
            args = tool.parameters.model_validate(params["args"])
            # Synchronous application tools run off the event loop; cancellation is cooperative.
            result = (
                await tool.execute(args)
                if inspect.iscoroutinefunction(tool.execute)
                else await asyncio.to_thread(tool.execute, args)
            )
            if inspect.isawaitable(result):
                result = await result
            if isinstance(result, BaseModel):
                result = result.model_dump(mode="json")
            await self._call("tool_result", {"id": params["id"], "result": result})
        except asyncio.CancelledError:
            raise
        except Exception as exc:  # noqa: BLE001 -- application tool exceptions become model-visible error results
            try:
                await self._call("tool_result", {"id": params["id"], "error": str(exc)})
            except BrowserUseError:
                pass

    async def _run(
        self,
        method: str,
        task: str,
        schema: type[BaseModel] | dict[str, Any] | None,
        options: dict[str, Any],
    ) -> RunResult:
        if schema is not None:
            options["schema"] = (
                _schema(schema.model_json_schema())
                if inspect.isclass(schema) and issubclass(schema, BaseModel)
                else _schema(schema)
            )
        try:
            result = await self._call(method, {"task": task, "options": options})
        except asyncio.CancelledError:
            await asyncio.shield(self.cancel())
            raise
        output = result.get("output")
        if (
            result["status"] == "completed"
            and inspect.isclass(schema)
            and issubclass(schema, BaseModel)
        ):
            output = schema.model_validate(output)
        return RunResult(result["status"], output, result["text"], result)

    async def run(
        self,
        task: str,
        *,
        schema: type[BaseModel] | dict[str, Any] | None = None,
        **options: Any,
    ) -> RunResult:
        return await self._run("run", task, schema, options)

    async def follow_up(
        self,
        task: str,
        *,
        schema: type[BaseModel] | dict[str, Any] | None = None,
        **options: Any,
    ) -> RunResult:
        return await self._run("followUp", task, schema, options)

    async def execute(self, code: str, **options: Any) -> dict[str, Any]:
        return await self._call("execute", {"code": code, "options": options})

    async def events(self) -> AsyncIterator[dict[str, Any]]:
        queue: asyncio.Queue[Any] = asyncio.Queue(maxsize=64)
        self._queues.add(queue)
        try:
            while not self._closed:
                item = await queue.get()
                if isinstance(item, Exception):
                    raise item
                if item is None:
                    return
                yield item
        finally:
            self._queues.discard(queue)

    async def pause(self) -> bool:
        return (await self._call("pause"))["paused"]

    async def resume(self) -> None:
        await self._call("resume")

    async def steer(self, text: str) -> None:
        await self._call("steer", {"text": text})

    async def cancel(self) -> None:
        await self._call("cancel")

    async def files(self) -> list[dict[str, Any]]:
        return await self._call("files")

    async def history(self) -> dict[str, Any]:
        return await self._call("history")

    async def save_history(self, path: str | None = None) -> str:
        return await self._call("saveHistory", {"path": path} if path else {})

    async def export_recording(self, path: str, **options: Any) -> str:
        return await self._call("exportRecording", {"path": path, "options": options})

    async def current_target(self) -> str | None:
        return await self._call("currentTarget")

    async def connect_browser(self, cdp_url: str, *, target_id: str | None = None) -> None:
        """Attach the browser of a session configured with browser={"kind": "pending"}
        (optionally with "timeoutMs", how long a browser cell waits for it; default 60 s).
        The model may already be running; its first browser cell waits for this."""
        params: dict[str, Any] = {"cdpUrl": cdp_url}
        if target_id:
            params["targetId"] = target_id
        await self._call("connectBrowser", params)

    async def close(self, *, keep_tabs: bool | str = False) -> None:
        """keep_tabs leaves the tabs this session opened for a later session;
        "current" keeps only the tab the agent is on."""
        if self._closing is None:
            self._closing = asyncio.create_task(self._close(keep_tabs))
        await asyncio.shield(self._closing)

    async def _close(self, keep_tabs: bool | str = False) -> None:
        if self._closed:
            return
        try:
            if self._process and self._process.returncode is None:
                try:
                    # A runtime that never received `create` has no session to close.
                    if self._configuring:
                        await asyncio.wait_for(
                            self._call("close", {"keepTabs": keep_tabs} if keep_tabs else None),
                            10,
                        )
                except (BrowserUseError, ConnectionError, asyncio.TimeoutError) as exc:
                    self._stderr = (self._stderr + f"\nGraceful close failed: {exc}")[
                        -16000:
                    ]
                if self._process.stdin:
                    self._process.stdin.close()
                try:
                    await asyncio.wait_for(self._process.wait(), 5)
                except asyncio.TimeoutError:
                    self._process.kill()
                    await self._process.wait()
        finally:
            self._closed = True
            self._broadcast(None)
            tasks = [
                task
                for task in [
                    self._reader,
                    self._stderr_task,
                    *self._tool_tasks.values(),
                ]
                if task
            ]
            for task in tasks:
                if not task.done():
                    task.cancel()
            await asyncio.gather(*tasks, return_exceptions=True)

    async def __aenter__(self) -> Self:
        return self

    async def __aexit__(self, *_exc: object) -> None:
        await self.close()

import type { ProtocolMapping } from 'devtools-protocol/types/protocol-mapping.js';
import { approveChromeConnection } from './browser.js';
import { positiveInteger } from './protocol.js';

type Commands = ProtocolMapping.Commands;
type Events = ProtocolMapping.Events;
type Pending = { resolve(value: unknown): void; reject(error: Error): void };
type Listener = {
  method: string;
  sessionId: string | undefined;
  accept(params: unknown): void;
  reject(error: Error): void;
};

/** Explicit commands and one-shot events over one flattened CDP WebSocket. No proxies. */
export class CDP {
  private nextId = 0;
  // Shared with the lazy connection. Observation follows protocol sessions, not JS variable names.
  private activity = {
    targets: new Map<string, string>(),
    parents: new Map<string, string>(),
    targetId: undefined as string | undefined,
  };
  get observationTargetId() {
    let targetId = this.activity.targetId;
    const visited = new Set<string>();
    while (targetId && this.activity.parents.has(targetId) && !visited.has(targetId)) {
      visited.add(targetId);
      targetId = this.activity.parents.get(targetId);
    }
    return targetId;
  }
  targetForSession(sessionId: string) {
    return this.activity.targets.get(sessionId);
  }
  /** Optional metadata observer; errors cannot change command delivery. Never receives responses. */
  observeCommand: ((method: string, params: unknown, sessionId?: string) => void) | undefined;
  /** Passive result tap. Exceptions cannot change command delivery. May contain page data. */
  observeResponse:
    ((method: string, params: unknown, result: unknown, sessionId?: string) => void) | undefined;
  observeEvent: ((method: string, params: unknown, sessionId?: string) => void) | undefined;
  private pending = new Map<number, Pending>();
  private listeners = new Set<Listener>();
  private constructor(
    private socket: WebSocket | undefined,
    readonly timeoutMs: number,
  ) {
    if (!socket) return;
    socket.addEventListener('message', ({ data }) => {
      try {
        const message = JSON.parse(String(data));
        if (message.id !== undefined) {
          const request = this.pending.get(message.id);
          if (message.error)
            request?.reject(new Error(`CDP ${message.error.code}: ${message.error.message}`));
          else request?.resolve(message.result);
        } else {
          this.observeEvent?.(message.method, message.params, message.sessionId);
          if (message.method === 'Target.detachedFromTarget')
            this.activity.targets.delete(message.params.sessionId);
          for (const listener of [...this.listeners]) {
            if (listener.method === message.method && listener.sessionId === message.sessionId)
              listener.accept(message.params);
          }
        }
      } catch {
        this.fail(new Error('Malformed CDP message.'));
        socket.close();
      }
    });
    socket.addEventListener('close', () =>
      this.fail(new Error('CDP connection closed. Inspect state before retrying.')),
    );
    socket.addEventListener('error', () => this.fail(new Error('CDP connection failed.')));
  }

  private endpoint: string | undefined;
  private approveConnection = false;
  private delegate: Promise<CDP> | undefined;
  private closed = false;

  /** Defer network access until the first browser operation. Never replay a command. */
  static lazy(endpoint: string, timeoutMs = 15_000, approveConnection = false) {
    const connection = new CDP(undefined, timeoutMs);
    connection.endpoint = endpoint;
    connection.approveConnection = approveConnection;
    return connection;
  }
  private connected(): Promise<CDP> {
    if (this.closed) return Promise.reject(new Error('CDP connection is closed.'));
    this.delegate ??= CDP.connect(this.endpoint!, this.timeoutMs, this.approveConnection)
      .then((connection) => {
        if (this.closed) {
          connection.close();
          throw new Error('CDP connection is closed.');
        }
        connection.activity = this.activity;
        connection.observeEvent = (method, params, session) =>
          this.observeEvent?.(method, params, session);
        connection.observeCommand = (method, params, sessionId) =>
          this.observeCommand?.(method, params, sessionId);
        return connection;
      })
      .catch((error) => {
        this.delegate = undefined;
        throw error;
      });
    return this.delegate;
  }

  static async connect(
    endpoint: string,
    timeoutMs = 15_000,
    approveConnection = false,
  ): Promise<CDP> {
    if (approveConnection && process.platform !== 'darwin')
      throw new Error('Chrome approval is macOS only.');
    positiveInteger('timeoutMs', timeoutMs);
    // A cold cloud browser can take seconds to answer; that must not fail a short operation timeout.
    const connectMs = Math.max(timeoutMs, 15_000);
    const url = new URL(endpoint);
    if (url.protocol === 'http:' || url.protocol === 'https:') {
      url.pathname = `${url.pathname.replace(/\/$/, '')}/json/version`;
      const response = await fetch(url, { signal: AbortSignal.timeout(connectMs) });
      if (!response.ok) throw new Error(`CDP discovery failed (${response.status}).`);
      endpoint = ((await response.json()) as { webSocketDebuggerUrl: string }).webSocketDebuggerUrl;
    } else if (!['ws:', 'wss:'].includes(url.protocol))
      throw new Error('Unsupported CDP endpoint protocol.');
    const socket = new WebSocket(endpoint);
    const connection = new CDP(socket, timeoutMs);
    await new Promise<void>((resolve, reject) => {
      const approval = new AbortController();
      const finish = (error?: Error) => {
        approval.abort();
        clearTimeout(timer);
        socket.removeEventListener('open', open);
        socket.removeEventListener('error', failed);
        socket.removeEventListener('close', failed);
        if (error) {
          socket.close();
          reject(error);
        } else resolve();
      };
      const open = () => finish();
      const failed = () => finish(new Error('Could not connect to CDP endpoint.'));
      const timer = setTimeout(() => finish(new Error('CDP connection timed out.')), connectMs);
      socket.addEventListener('open', open, { once: true });
      socket.addEventListener('error', failed, { once: true });
      socket.addEventListener('close', failed, { once: true });
      if (approveConnection) {
        void (async () => {
          while (!approval.signal.aborted) {
            await new Promise((resolve) => setTimeout(resolve, 300));
            if (approval.signal.aborted) return;
            if ((await approveChromeConnection(approval.signal)) === 'ready') return;
          }
        })().catch((error) => {
          if (!approval.signal.aborted) finish(error);
        });
      }
    });
    return connection;
  }

  async send<M extends keyof Commands>(
    method: M,
    params: Commands[M]['paramsType'][0] = {} as Commands[M]['paramsType'][0],
    sessionId?: string,
  ): Promise<Commands[M]['returnType']> {
    // Capture the observer at dispatch, so late responses cannot enter a later cell.
    const observe = this.observeResponse;
    const result = this.endpoint
      ? await (await this.connected()).send(method, params, sessionId)
      : await this.sendMessage(method, params, sessionId);
    if (method === 'Target.attachToTarget') {
      const attached = result as Commands['Target.attachToTarget']['returnType'];
      const target = (params as Commands['Target.attachToTarget']['paramsType'][0]).targetId;
      this.activity.targets.set(attached.sessionId, target);
      this.activity.targetId = target;
    } else if (method === 'Target.detachFromTarget') {
      const detached = params as Commands['Target.detachFromTarget']['paramsType'][0];
      if (detached?.sessionId) this.activity.targets.delete(detached.sessionId);
    } else if (method === 'Target.closeTarget' && (result as { success?: boolean }).success) {
      const target = (params as Commands['Target.closeTarget']['paramsType'][0]).targetId;
      if (this.observationTargetId === target || this.activity.targetId === target)
        this.activity.targetId = undefined;
      for (const [id, value] of this.activity.targets)
        if (value === target) this.activity.targets.delete(id);
      this.activity.parents.delete(target);
    }
    if (method === 'Target.getTargets' || method === 'Target.getTargetInfo') {
      const infos =
        method === 'Target.getTargets'
          ? (result as Commands['Target.getTargets']['returnType']).targetInfos
          : [(result as Commands['Target.getTargetInfo']['returnType']).targetInfo];
      for (const info of infos)
        if (info.type === 'iframe' && info.parentFrameId)
          this.activity.parents.set(info.targetId, info.parentFrameId);
    }
    if (method === 'Page.getFrameTree' && sessionId) {
      const targetId = this.targetForSession(sessionId);
      const visit = (tree: import('devtools-protocol').Protocol.Page.FrameTree) => {
        if (targetId && tree.frame.id !== targetId)
          this.activity.parents.set(tree.frame.id, targetId);
        tree.childFrames?.forEach(visit);
      };
      visit((result as Commands['Page.getFrameTree']['returnType']).frameTree);
    }
    try {
      observe?.(method, params, result, sessionId);
    } catch {}
    return result;
  }

  private sendMessage<M extends keyof Commands>(
    method: M,
    params: Commands[M]['paramsType'][0],
    sessionId?: string,
  ): Promise<Commands[M]['returnType']> {
    if (!this.socket || this.socket.readyState !== WebSocket.OPEN)
      return Promise.reject(new Error('CDP connection is closed.'));
    if (this.pending.size >= 256)
      return Promise.reject(new Error('Too many pending CDP commands (256).'));
    if (sessionId) this.activity.targetId = this.targetForSession(sessionId);
    try {
      this.observeCommand?.(method, params, sessionId);
    } catch {}
    const id = ++this.nextId;
    return new Promise((resolve, reject) => {
      const finish = (error?: Error, value?: unknown) => {
        clearTimeout(timer);
        this.pending.delete(id);
        if (error) reject(error);
        else resolve(value as Commands[M]['returnType']);
      };
      const timer = setTimeout(
        () =>
          finish(
            new Error(`CDP ${method} exceeded ${this.timeoutMs} ms; the action may have happened.`),
          ),
        this.timeoutMs,
      );
      this.pending.set(id, {
        resolve: (value) => finish(undefined, value),
        reject: (error) => finish(error),
      });
      try {
        this.socket!.send(
          JSON.stringify({ id, method, params, ...(sessionId ? { sessionId } : {}) }),
        );
      } catch (error) {
        finish(error instanceof Error ? error : new Error(String(error)));
      }
    });
  }

  waitFor<M extends keyof Events>(
    method: M,
    options: {
      sessionId?: string;
      timeoutMs?: number;
      signal?: AbortSignal;
      predicate?: (event: Events[M][0]) => boolean;
    } = {},
  ): Promise<Events[M][0]> {
    const timeoutMs = positiveInteger('timeoutMs', options.timeoutMs ?? this.timeoutMs);
    if (this.endpoint)
      return this.connected().then((connection) => connection.waitFor(method, options));
    const promise = new Promise<Events[M][0]>((resolve, reject) => {
      const finish = (error?: Error, value?: unknown) => {
        clearTimeout(timer);
        this.listeners.delete(listener);
        options.signal?.removeEventListener('abort', abort);
        if (error) reject(error);
        else resolve(value as Events[M][0]);
      };
      const listener: Listener = {
        method,
        sessionId: options.sessionId,
        accept: (value) => {
          try {
            if (!options.predicate || options.predicate(value as Events[M][0]))
              finish(undefined, value);
          } catch (e) {
            finish(e instanceof Error ? e : new Error(String(e)));
          }
        },
        reject: (error) => finish(error),
      };
      const abort = () => finish(new Error(`CDP ${method} wait cancelled.`));
      const timer = setTimeout(
        () => finish(new Error(`CDP event ${method} exceeded ${timeoutMs} ms.`)),
        timeoutMs,
      );
      this.listeners.add(listener);
      options.signal?.addEventListener('abort', abort, { once: true });
      if (options.signal?.aborted) abort();
      else if (this.socket?.readyState !== WebSocket.OPEN)
        finish(new Error('CDP connection is closed.'));
    });
    // A caller commonly registers a waiter before an action, then awaits it afterward.
    void promise.catch(() => {});
    return promise;
  }

  private fail(error: Error) {
    for (const request of [...this.pending.values()]) request.reject(error);
    for (const listener of [...this.listeners]) listener.reject(error);
  }
  close() {
    this.closed = true;
    this.activity.targets.clear();
    this.activity.parents.clear();
    this.activity.targetId = undefined;
    void this.delegate?.then((connection) => connection.close()).catch(() => {});
    this.fail(new Error('CDP connection closed.'));
    this.socket?.close();
  }
}
